function a=v3_detail_metrics(r,s,folder)
% Additional measured evidence; never substitutes commands for true actuator outputs.
p=vehicle_params;t=r.states.Time(:);x=squeeze(r.states.Data);b=load(fullfile(folder,'reference_bank.mat'));m=jsondecode(fileread(fullfile(folder,'metrics.json')));st=jsondecode(fileread(fullfile(folder,'run_status.json')));bc=jsondecode(fileread(fullfile(folder,'build_config.json')));
a=struct('id',s.id,'group',s.group,'pair_id',s.pair_id,'arm','A','pitch_step_deg',s.amplitude,'onset_s',s.onset,'reference_profile',s.profile,'reference_q0',b.q_ref(:,1,1),'initial_state',b.x0,'reference_initial_pitch_deg',rad2deg(quat2eul(b.q_ref(:,1,1)')*[0;1;0]),'absolute_pitch_min_deg',min(rad2deg(x(:,2))),'absolute_pitch_max_deg',max(rad2deg(x(:,2))),'actual_end_s',t(end),'status',m.status,'settled_criterion_pass',strcmp(m.status,'SUCCESS'),'source_git_sha','','model_sha256',bc.model_sha256,'bank_sha256',bc.bank_sha256,'controller_config',s.pid,'wall_time_s',st.wall_time_s,'gamma0',[],'H0',[],'A0',[],'sigma_min0',NaN,'frame_angle_abs_peak_rad',NaN,'frame_speed_abs_peak_radps',NaN,'frame_acceleration_abs_peak_radps2',NaN,'cmg_torque_norm_peak_Nm',NaN,'cmg_torque_norm_rms_Nm',NaN,'physical_bounds_pass',true,'truth_period_pass',max(abs(diff(t)-.001))<1e-9,'upper_period_pass',false,'inner_period_pass',false,'sqp_limit_observed',NaN,'inner_fallbacks',NaN);
pre=jsondecode(fileread(fullfile(folder,'..','..','..','config','preflight.json')));a.source_git_sha=pre.git_sha;a.truth_period_pass=v3_period_matches(t,.001);a.period_audit_policy='All internal intervals must equal nominal period; only terminal output may be a shorter positive interval';a.truth_last_interval_s=t(end)-t(end-1);
d=squeeze(r.delta_actual.Data);v=squeeze(r.delta_dot.Data);a.surface_angle_saturation_pct=100*mean(abs(d)>=p.vehicle.delta_max(:)'-1e-5,1);a.surface_rate_saturation_pct=100*mean(abs(v)>=p.vehicle.delta_dot_max(:)'-1e-5,1);a.physical_bounds_pass=all(abs(d)<=p.vehicle.delta_max(:)'+1e-6,'all') && all(abs(v)<=p.vehicle.delta_dot_max(:)'+1e-6,'all');
if s.cmg
 a.arm='B';g=x(1,7:10);a.gamma0=g;a.H0=sum(p.cmg.h0*(p.s0.*cos(g)+p.gxs0.*sin(g)),2);a.A0=p.cmg.h0*(-p.s0.*sin(g)+p.gxs0.*cos(g));a.sigma_min0=min(svd(a.A0));nu=squeeze(r.nu_actual.Data);ac=squeeze(r.cmg_acceleration.Data);tc=squeeze(r.cmg_torque.Data);a.frame_angle_abs_peak_rad=max(abs(x(:,7:10)),[],'all');a.frame_speed_abs_peak_radps=max(abs(nu),[],'all');a.frame_acceleration_abs_peak_radps2=max(abs(ac),[],'all');a.cmg_torque_norm_peak_Nm=max(vecnorm(tc,2,2));a.cmg_torque_norm_rms_Nm=sqrt(mean(sum(tc.^2,2)));a.physical_bounds_pass=a.physical_bounds_pass && all(abs(nu)<=p.cmg.gdot_max+1e-6,'all') && all(abs(ac)<=p.cmg.gddot_max+1e-6,'all');
end
f=dir(fullfile(folder,'*_torque_feedback.mat'));if ~isempty(f),z=load(fullfile(folder,f(1).name));a.inner_period_pass=v3_period_matches(z.diagnostics.time,.02);a.inner_fallbacks=sum(z.diagnostics.fallback);end
f=dir(fullfile(folder,'*_authority.mat'));if ~isempty(f),z=load(fullfile(folder,f(1).name));a.upper_period_pass=v3_period_matches(z.control_times,.2);iterations=cellfun(@(d)d.sqp_attempted,z.diagnostics);a.sqp_limit_observed=max(iterations);a.upper_period_pass=a.upper_period_pass && a.sqp_limit_observed<=4;else,z=load(fullfile(folder,'pid_diagnostics.mat'));a.upper_period_pass=v3_period_matches(z.times,.2);end
paper_json(fullfile(folder,'detail_metrics.json'),a);
if strcmp(s.group,'E2')
 [qref,~]=paper_reference_series(b,t);q=paper_euler_quaternions(x(:,1:3));er=rad2deg(2*acos(min(1,abs(sum(q.*qref,2)))));ev=s.events;if isempty(ev),ev=[s.onset s.transition 0 s.amplitude 0];end;rows={};A=readtable(fullfile(folder,'actuator_timeseries_20ms.csv'));
 for j=1:size(ev,1),start=ev(j,1);finish=start+ev(j,2);next=inf;if j<size(ev,1),next=ev(j+1,1);end;stop=min([finish+10,next,t(end)]);during=t>=start & t<=finish;after=t>finish & t<=stop;[~,i]=min(abs(A.time_s-(start-.2)));z=struct('case_id',s.id,'event_index',j,'onset_s',start,'finish_s',finish,'post_end_s',stop,'full_maneuver',t(end)>=finish,'full_post_10s',t(end)>=finish+10 && next>=finish+10,'maneuver_rmse_deg',sqrt(mean(er(during).^2)),'maneuver_peak_deg',max(er(during)),'post_rmse_deg',sqrt(mean(er(after).^2)),'pre_H_Nms',norm(A{i,28:30}),'pre_sigma_min',A.sigma_min(i),'pre_pitch_positive_support_Nm',A.next_y_positive_support_Nm(i),'pre_pitch_negative_support_Nm',A.next_y_negative_support_Nm(i));rows{end+1}=z;end
 writetable(struct2table([rows{:}],'AsArray',true),fullfile(folder,'event_metrics.csv'));
end
end
